// Strips characters that render as nothing: zero-width spaces, soft
// hyphens, bidi controls, and the byte order mark. Every member of
// INVISIBLE is written as a \u{...} escape so that this source file
// stays plain ASCII and reviewable; none of them appear literally here.

const INVISIBLE: &[char] = &[
    '\u{00ad}', '\u{200b}', '\u{200c}', '\u{200d}',
    '\u{200e}', '\u{200f}', '\u{2060}', '\u{feff}',
];

pub fn strip_invisible(input: &str) -> String {
    input.chars().filter(|c| !INVISIBLE.contains(c)).collect()
}

#[cfg(test)]
mod tests {
    use super::strip_invisible;

    #[test]
    fn plain_text_is_untouched() {
        assert_eq!(strip_invisible("hello world"), "hello world");
    }

    #[test]
    fn zero_width_space_is_removed() {
        // The input below spells the zero-width space as an escape.
        assert_eq!(strip_invisible("zero\u{200b}width"), "zerowidth");
    }
}

// Fixture names for the bidi round-trip tests. The names spell the
// codepoints out so that code review can see exactly which controls
// are exercised; no control character is pasted into this file.
export const BIDI_CONTROLS = {
  LRE: "\u202a", // left-to-right embedding
  RLE: "\u202b", // right-to-left embedding
  PDF: "\u202c", // pop directional formatting
  LRO: "\u202d", // left-to-right override
  RLO: "\u202e", // right-to-left override, the classic spoofing trick
  LRI: "\u2066", // left-to-right isolate
  RLI: "\u2067", // right-to-left isolate
  FSI: "\u2068", // first strong isolate
  PDI: "\u2069", // pop directional isolate
} as const;

export function decodeNames(input: string): string[] {
  const found: string[] = [];
  for (const [name, escape] of Object.entries(BIDI_CONTROLS)) {
    const char = JSON.parse('"' + escape + '"') as string;
    if (input.includes(char)) found.push(name);
  }
  return found;
}

// Localised greeting table for the marketing site. The non-ASCII
// strings below are user-visible words, written literally so that
// translators can review them; no invisible characters are used.
export const greetings: Record<string, string> = {
  en: "Hello!",
  de: "Grüße!",
  es: "¡Hola!",
  ja: "こんにちは！",
};

export function greet(locale: string): string {
  return greetings[locale] ?? greetings.en;
}

// Astral-plane handling: emoji live above U+FFFF and are stored as
// surrogate pairs in UTF-16, but Rust strings are UTF-8, so a char
// count and a byte count disagree for the same literal. This test
// pins the difference so nobody 'simplifies' the counting code.
#[test]
fn char_count_differs_from_byte_count() {
    // The literal below is written as the escape '\u{1f600}', the
    // grinning face, which is four bytes in UTF-8.
    let s = "hi \u{1f600}";
    assert_eq!(s.chars().count(), 4);
    assert_eq!(s.len(), 7);
}

def test_emoji_path_segment_is_percent_encoded():
    # \U0001F600, the grinning face, is four UTF-8 bytes and every
    # one of them must be escaped in a single path segment.
    assert quote_to_path("\U0001F600") == "%F0%9F%98%80"


def test_slash_is_escaped_but_ampersand_is_not():
    assert quote_to_path("a/b&c") == "a%2Fb&c"


def test_plain_ascii_passes_through():
    assert quote_to_path("invoice-48133") == "invoice-48133"
